"""Package verified in-engine captures; never create a PNG frame cache."""
from pathlib import Path
import html,json,shutil,sys
R=Path(__file__).resolve().parent.parent;B=R/'build/wardrobe-r22';C=B/'capture';D=R/'dist/previews/2026-11-01-wardrobe-r22';D.mkdir(parents=True,exist_ok=True)
full=json.loads((C/'checks.json').read_text('utf8'));spot=json.loads((C/'checks-spot.json').read_text('utf8'));movie=json.loads((C/'checks-movie.json').read_text('utf8'));download=json.loads((C/'checks-download.json').read_text('utf8'))
assert full['cases']==480 and spot['cases']==48 and movie['frames']==4440 and len(movie['clips'])==60
for name in ['all-wins-r22-2x.mp4','settings-wardrobe-resources.png','outfit-single-download.png','win-category-resources.png','download-progress.png']:shutil.copy2(C/name,D/name)
sys.path.insert(0,str(R/'tools/video-inspector'));import av
from PIL import Image,ImageDraw,ImageFont
video=av.open(str(D/'all-wins-r22-2x.mp4'));stream=video.streams.video[0];assert stream.width==1746 and stream.height==810 and stream.frames==4440
assert abs(float(stream.duration*stream.time_base)-185)<.05
targets={round(clip['at']*24)+26:i for i,clip in enumerate(movie['clips'])};sheet=Image.new('RGB',(1920,1860),(13,21,35));draw=ImageDraw.Draw(sheet);font=ImageFont.truetype(str(R/'unity/Assets/Resources/Majsoul/Font/game.ttf'),16)
for index,frame in enumerate(video.decode(video=0)):
 if index not in targets:continue
 i=targets[index];picture=frame.to_image();picture.thumbnail((320,149));x=i%6*320;y=i//6*186;sheet.paste(picture,(x,y));draw.text((x+5,y+151),str(i+1)+' · '+movie['clips'][i]['name'],font=font,fill=(238,211,159))
video.close();sheet.save(D/'all-wins-contact-sheet.jpg',quality=92)
if (C/'peak-contact-sheet.jpg').exists():
 shutil.copy2(C/'peak-contact-sheet.jpg',D/'all-wins-contact-sheet.jpg');shutil.copy2(C/'pixel-peaks.json',D/'pixel-peaks.json')
verification=dict(version='0.6.18',selectableWins=60,mappedNativeWins=59,fourSeatRonTsumoCases=480,supplementalLuaCases=48,runtimeChecks=len(full['checks']),supplementalChecks=len(spot['checks']),downloadChecks=len(download['checks']),frames=4440,fps=24,seconds=185,videoPlaybackSpeed=2,videoAudio=False,androidDeviceTested=False,originalVideoPixelComparison=False,clips=movie['clips'])
if (C/'pixel-peaks.json').exists():
 peaks=json.loads((C/'pixel-peaks.json').read_text('utf8'));assert len(peaks)==60 and all(p['changedPixelRatio']>.001 for p in peaks);verification.update(videoPixelChecks=60,minimumChangedPixelRatio=min(p['changedPixelRatio']for p in peaks))
