screens=''.join('<figure><img src="'+name+'.png"><figcaption>'+caption+'</figcaption></figure>'for name,caption in [('settings-wardrobe-resources','设置 → 资源 → 装扮资源'),('outfit-single-download','装扮页的单件下载与下载后选用'),('win-category-resources','和牌分类列表及批量下载'),('download-progress','实际下载进度，支持取消续传')])
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>云间日麻 · 和牌特效与装扮资源</title><style>*{box-sizing:border-box}body{margin:0;background:#0c1523;color:#e9edf3;font:16px/1.8 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:28px 22px}h1{font-size:30px}h2{font-size:23px;margin-top:30px}p{color:#b8c6d9}video{display:block;width:100%;background:#030710;border:1px solid #40516a;border-radius:8px}.buttons{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:18px}button{border:1px solid #40516a;background:#17283e;color:#ebd2a4;padding:10px 5px;border-radius:5px;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0;background:#15243a;border:1px solid #344761;border-radius:6px;overflow:hidden}img{display:block;width:100%}figcaption{padding:10px 14px}a{color:#e8c68b}footer{border-top:1px solid #344761;margin-top:30px;padding-top:15px;color:#a7b6cb;font-size:14px}@media(max-width:800px){.buttons{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}</style><main><h1>云间日麻 0.6.18 · 和牌特效与装扮资源</h1><p>59 款已定位原生和牌特效＋默认款。全部画面来自当前 Unity 游戏运行，按原版 Lua 处理新旧根节点、动画牌、渲染层级、声音、时序与回收。</p><video id="v" src="all-wins-r22-2x.mp4" controls preload="metadata" playsinline></video><p>总览为 2 倍速、无音轨，约 3 分 5 秒；游戏内使用正常速度并保留原版音效。点击名称跳转到对应款式。</p><div class="buttons">__BUTTONS__</div><h2>装扮下载</h2><p>基础包每类保留 3 款，手部保留 2 款可选。其他装扮支持资源页按类别批量下载、装扮页单独下载与选用、取消续传、校验安装和删除；开局资源准备支持局域网接收及基础替代。</p><div class="grid">__SCREENS__</div><h2>验证范围</h2><p>完成 480 个四座位荣和／自摸场景、48 个补充 Lua 场景及实际 HTTP 下载、续传、损坏包拒绝、使用期删除保护和中转检查。额外原生资源中未映射项与已过期缺失项已记录，不作为已完成款式宣传。</p><details><summary>全部效果关键帧</summary><img src="all-wins-contact-sheet.jpg"></details><footer>桌面运行检查已通过。原版视频逐像素对照、Android 真机 GPU／触摸及多手机热点联机仍需实测。<a href="verification.json">验证记录</a></footer></main><script>const v=document.getElementById('v');document.querySelectorAll('[data-at]').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.at);v.play();v.scrollIntoView({behavior:'smooth',block:'center'})})</script></html>'''
(D/'index.html').write_text(page.replace('__BUTTONS__',buttons).replace('__SCREENS__',screens),'utf8');print('R22 PREVIEW READY',D,'185s / 4440 frames / 60 chapters')
